INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(175000, 0, 0, 0, 0, 0, 0, 0, 0, '你说，是我手下某位骑士派你来的？$B$B很好。这类事情上，我宁可信任他们的判断，也不信我自己的。我便接受你的效力了，至于身份……侍从？还是雇佣兵？$B$B<塞文·达伦加尔摆了摆手，仿佛不屑于计较名分之事。>$B$B请原谅，我实在难以理清思绪。我把自己关在这里好几个钟头了，一直在设法说服贵族议会派兵前往斯卡德尔德……收效甚微。', 0),
(175001, 0, 0, 0, 0, 0, 0, 0, 0, '<你能清楚地看到，失败明明白白地写在这位老人含泪的眼中。>$B$B要说服这班懦夫主动一次，非得神迹不可。你自己也听见了：只要塞伦娅·冷沼女士——她家族的最后一人——拒绝正式请求援军，而这她永远不会做，贵族议会就不会出手干预。$B$B我族人的血会染上他们的手，却不会染上我的。我不会坐视斯卡德尔德就此凋零。', 0),
(175002, 0, 0, 0, 0, 0, 0, 0, 0, '<女仆攥紧围裙下的拳头，指节发白。>$B$B你是来找阿拉松大人的吗？$B$B那你来迟了。格雷斯基那帮恶棍，奉那个碎嘴的塞伦娅女士之命，几个钟头前把他抓走了。他们连让他穿上靴子的工夫都不给。$B$B如今他们正把庄园翻个底朝天！你信吗？他们竟指控达伦加尔家族犯下叛国大罪！', 0),
(175003, 0, 0, 0, 0, 0, 0, 0, 0, '这是……$B$B<翻动日志纸页之间，卡德米拉的神情由悲转惑。>$B$B我一点也看不懂。$B$B<卡德米拉摇了摇头。>$B$B这确实是阿拉松大人的笔迹，绝无差错。天啊，天啊！他怎么会……？', 0),
(175004, 0, 0, 0, 0, 0, 0, 0, 0, '<破裂的木箱上印着联盟的徽记。看来它们是被人慌慌张张从井口抛下来的。坠落摔碎了好几只，暴风城的钢材散落在洞穴潮湿的地面上。>$B$B<这不是废物。这是一座军械库。>', 0),
(175005, 0, 0, 0, 0, 0, 0, 0, 0, '<队长在远处朝你招手，手势阴沉。>$B$B女仆已经全都告诉我了。$B$B我们早已深疑达伦加尔家族在密谋对抗格雷斯基的政府，可没想到他们竟敢做到这一步……$B$B他们在给艾尔迪尔人提供武器！我猜他们的用意是加深斯卡德尔德面临的危机，进一步动摇塞伦娅女士的统治。', 0),
(175006, 0, 0, 0, 0, 0, 0, 0, 0, '<即便隔着遮住塞伦娅面容的面纱，你仍感到她目光的寒意，如双箭般刺穿你。>$B$B这真是与达伦加尔家族相称的转折。我会亲自确保，史书将他们的姓氏记为背叛的同义词。$B$B至于你，斯卡德尔德感谢你。以你的才干，能为这个省份效上大力。', 0),
(175007, 0, 0, 0, 0, 0, 0, 0, 0, '你是塞伦娅女士举荐来的，是吗？$B$B<德雷温给你的印象是那种不必提高嗓门也能赢得敬重的人。他那双灰眼睛将你从头到脚打量了一遍。>$B$B斯卡德尔德在两件事上格外慷慨：雨水，和麻烦。圣光知道，能召集的每一个人手我们都得用上。很好！你看起来能干事，也肯用功。光是这两点，这里大多数人就已比不上你了！', 0),
(175009, 0, 0, 0, 0, 0, 0, 0, 0, '这么说，他们终于肯派个人来了！迟来总胜过不来，我想；哪怕你只是个卖剑的。$B$B请原谅我拿你出气。我把报告送去给德雷温爵士已整整两星期，从那以后格雷斯基就再没半点回音。$B$B我知道卫队被艾尔迪尔人和霜鬃巨魔拖得兵力单薄，可这村子里出了件事，比路边的伏击更该让我们担心。', 0),
(175010, 0, 0, 0, 0, 0, 0, 0, 0, '新来的兵？$B$B既然领主指挥官相信多一双手就能让天平向我们倾斜，你必定有过人之处。$B$B你对霜鬃巨魔了解多少？你可知道自己正踏进什么境地？砍翻几个强盗，或者对付些围着兽皮的野蛮人，那是一回事。战场则完全是另一回事。$B$B况且霜鬃巨魔是绝不容情的敌人。', 0),
(175011, 0, 0, 0, 0, 0, 0, 0, 0, '你是德雷温爵士派来的，是吗？$B$B好，好。我知道格雷斯基的情形不妙。巨魔的威胁、王者大道被截断……$B$B<神父疲惫而紧张地叹了口气。>$B$B那些墓窖。我就墓窖的事写信给领主指挥官，不过最好还是让你亲眼看一看。', 0),
(175012, 0, 0, 0, 0, 0, 0, 0, 0, '这么说，是格雷斯基来的那位牧师派你来的。那人叫什么来着？肯西斯？康蒂斯？昆蒂尔？呸！$B$B说实话，格雷斯基卫队来修道院这儿，除了碍事也做不了什么。我们如今这样反倒更好。$B$B不过既然你来了，我倒能想到一两件你可以搭把手的事。', 0),
(175013, 0, 0, 0, 0, 0, 0, 0, 0, '圣光就在这里，在布道与祈祷之中。但它也在你挑战的那些见习者的惨叫、鲜血与泪水之中。$B$B你帮了他们一个忙。「棍棒底下出孝子」，我父亲过去常说。他常说很多话，大多是胡扯，但在这件事上……在这件事上，他说得对。', 0),
(175014, 0, 0, 0, 0, 0, 0, 0, 0, '阿姆罗德神父派你来的……？呃啊！$B$B<迪亚洛斯失血过多，似乎已几乎不省人事。>$B$B这些穴居怪和别的同类不一样。它们伏击了我们。是陷阱。全是陷阱。$B$B活下来的只剩我一个……', 0),
(175015, 0, 0, 0, 0, 0, 0, 0, 0, '那些穴居怪渣滓已经成了历史。很好。$B$B别让它们的死压在你心上——就像我派去处理它们的那些十字军的死，也从不压在我的良心上。$B$B一来，穴居怪没有灵魂。二来，那些十字军曾发誓要以性命侍奉圣光。', 0),
(175016, 0, 0, 0, 0, 0, 0, 0, 0, '这是什么？$B$B<恩哈伦端详着这件神器，目光中好奇与厌恶各占一半。>$B$B那些可憎的东西！我从没想过它们竟会有自己的宗教，竟有足够的智力。这真令人厌恶。一种与诺莫瑞根的辐射纠缠在一起的信仰，简直了。$B$B这不可能是巧合。诺莫瑞根的一切都没有原样幸存下来。若我的怀疑没错，那辐射改变了这些穴居怪：它赋予了它们一定程度的智力。$B$B把它们杀掉，不过是图一时痛快。', 0),
(175017, 0, 0, 0, 0, 0, 0, 0, 0, '一个国王？<阿姆罗德神父放声大笑，那笑声洪亮而充满嘲弄。>$B$B那些畜生。它们连自己呼吸的空气都不配。一个国王。一个国王！接下来还会有什么？公主？吟游诗人？教士？$B$B<他的语调一变，变得冷硬，脸色也阴沉下来。>$B$B死亡是唯一对这类野兽管用的药。', 0),
(175018, 0, 0, 0, 0, 0, 0, 0, 0, '哦，谢谢你，太感谢了！你找回的东西比我敢指望的还多，至少够让我免于破产。$B$B我会试着修好马车，等蒂托一康复，我就继续往格雷斯基去。$B$B我不知道该怎么报答你，但我永远欠你这份情。', 0),
(175019, 0, 0, 0, 0, 0, 0, 0, 0, '你回来时身上染着红。很好。$B$B多亏了你，这片林子稍微安全了些。暴风城卫队会尽力守住这一带；即便如此，若你还打算继续往斯卡德尔德去，务必小心行事。$B$B格雷斯基卫队传来的报告提醒我们要提防艾尔迪尔。他们的袭击似乎越来越频繁了。', 0),
(175020, 0, 0, 0, 0, 0, 0, 0, 0, '有鱼咬钩了！这一定多亏了你。$B$B非常感谢你的帮助。我拿不出什么像样的东西，但请收下这个，聊表谢意。', 0),
(175021, 0, 0, 0, 0, 0, 0, 0, 0, '<渔夫接过草，在两手之间揉搓起来。等揉成糊状，他便直接敷在伤口上。>$B$B啊啊啊！你不知道这有多刺人……可越是蜇，越是能治好……$B$B太感谢你了。我已经感觉到知觉在回来了。接下来的事我自己应该应付得来，不过在你走之前，请收下这个，算是对你帮忙的谢礼。', 0),
(175022, 0, 0, 0, 0, 0, 0, 0, 0, '你……你做到了！？哇哦哦！$B$B等我长大了，真希望能像你一样勇敢。太感谢你了！$B$B这个给你，收着吧。在下水道里……我用不着它了。', 0),
(175023, 0, 0, 0, 0, 0, 0, 0, 0, '<尽管外表如此，眼前这生物眼中仍残留着一丝人性，让人难以将它完全视作怪物。>$B$B等等！等等。我。我和别的不一样。还会想。会说话。我们说话？行吗？$B$B矿工。挖矿。洞。懂吗？塌了！石头，还有死人。矿工困住。饿。很饿。我们吃死人。然后……然后爪子长。毛长。牙长。$B$B变成怪物！好多疯了。有的没疯。有的像我。有的怕。', NULL),
(175024, 0, 0, 0, 0, 0, 0, 0, 0, '一张新面孔，而且这回你手里没拿草叉和火把。开头还不算坏。说说吧，是什么事让你来找我？$B$B<你讲述了阿尔托·比尔伯格的事，以及矿工们似乎遭到的诅咒，那诅咒把他们变成了豺狼人。>$B$B真典型。他们惧怕你、鄙夷你，直到某天突然需要你。可这么多年，我一直活在异类的身份里，受着邓希尔人的蔑视和不断的猜疑。$B$B我凭什么要帮他们？', 0),
(175026, 0, 0, 0, 0, 0, 0, 0, 0, '没成功，对吧？我从你脸上就看出来了。$B$B<贝尔德雷德的脸扭成一团，满是厌恶。那神情似乎是真心的。>$B$B这样的话，恐怕我也无能为力了。我本可以去问我的女巫集会，可她们远在天边，正忙着跟格雷斯基打一场毫无意义的仗。再说，就算她们肯帮忙，开出的价码也远不是你付得起的。$B$B不过……', 0),
(175027, 0, 0, 0, 0, 0, 0, 0, 0, '<阿玛兰瑟的注视让人有种被看穿的赤裸感。她的双眼是两口深不见底的记忆之井。>$B$B战士背负的，是一颗比剑更沉重的心。我知道你为何来到我面前。你的努力可敬，你的心意纯粹。$B$B但我帮不了你。$B$B镀金谷正熬着黑暗的日子，我的力量也随着森林的生机一同衰落。$B$B恐怕我无法相助。除非我们先挫败那笼罩着我们所有人的威胁。', NULL),
(175028, 0, 0, 0, 0, 0, 0, 0, 0, '今天没风……你得等我们把手上这些磨完。$B$B之后你才能磨你的小麦。', 0),
(175029, 0, 0, 0, 0, 0, 0, 0, 0, '瞧瞧！你带回了足够多的面粉，太好了。$B$B名满天下的邓希尔馅饼又少了一样要操心的材料。', 0),
(175030, 0, 0, 0, 0, 0, 0, 0, 0, '材料全齐了！$B$B你要我现在就开始做，还是你的馋劲儿还没上来，甜食家？$B$B呸，这还用问……香味一飘出来，你的口水就止不住了！', 0),
(175031, 0, 0, 0, 0, 0, 0, 0, 0, '此时此刻，整个斯卡德尔德都在羡慕你。说真的；你知道有多少人愿意跟你换个位置吗？第一次品尝邓希尔馅饼……$B$B好好享受这一刻。慢慢吃，别急。吃个饱。第一口，你一辈子都忘不了！', 0),
(175032, 0, 0, 0, 0, 0, 0, 0, 0, '护符，你找到了！$B$B你根本不知道自己把我从多大的困境里拉了出来。现在我可以专心准备这批货了。晚上也终于能睡个安稳觉。$B$B要是你愿意，等一切准备妥当我就通知你。我想，你已经挣得了亲眼看看镀金谷的资格。', 0),
(175033, 0, 0, 0, 0, 0, 0, 0, 0, '一张新面孔。嗯。看你背上的货包，你送来的应该就是我的订单。那么是达隆德派你来的。$B$B好了，朋友，喘口气，把心放宽。在这座圣所里，你找不到任何不是你随身带来的邪恶。', NULL),
(175034, 0, 0, 0, 0, 0, 0, 0, 0, '克雷斯特海恩的人民感谢你。$B$B这些熊死了，这一带就能安宁，它们的毛皮也能在丹莫罗的寒风吹起时为人御寒。', 0),
(175035, 0, 0, 0, 0, 0, 0, 0, 0, '站住。蹲下，不然你会把我们都害死。前面就是艾尔德梅因洞窟，说它是艾尔迪尔的老窝一点也不为过。$B$B在格雷斯基，有人为艾尔德梅因首领的人头出了一大笔钱。一想到这个我就直流口水。$B$B<兰德克咬紧牙关，压住一声痛哼。一支箭插在他的膝盖上。>$B$B该死。', 0),
(175036, 0, 0, 0, 0, 0, 0, 0, 0, '你。$B$B<雷格·安拉莫尔拦住你，一只手按在你肩上。紧接着，他把鼻子凑近你伪装用的那身偷来的毛皮。他的脸皱成一团。>$B$B你浑身都是死人的味道。但我没见过你这张脸。艾尔德梅因洞窟可不是你出生的那个可怜小村庄。真正的艾尔迪尔才会来这里。那些拥有战士之心的人。来训练。来杀戮。', 0),
(175039, 0, 0, 0, 0, 0, 0, 0, 0, '干得好。何止是好。如果克雷斯特海恩的民兵都像你这样，这场内战几年前就该结束了。$B$B你站对了边，朋友。不像我的兄弟。相信我，我试过让他明白道理。但根本没办法。$B$B我做了我不得不做的事。是的，长官。我做了唯一明智的选择。', 0),
(175040, 0, 0, 0, 0, 0, 0, 0, 0, '<阿拉莉娅的脸上写满了痛苦、绝望与毁灭。她善良的眼睛背后，有什么东西碎裂了。那是永远无法愈合的东西。永远。今生不行，来世不行，哪一世都不行。>$B$B我……为什么？为什么是我？为什么是我的儿子们？$B$B阿贝隆。噢，阿贝隆。死了。死在自己兄弟的手里。$B$B我到底做错了什么？', 0),
(175042, 0, 0, 0, 0, 0, 0, 0, 0, '你把那些亡灵处理掉了吗？$B$B感谢圣光！也感谢领主指挥官派你过来！当然，也要感谢你亲手了结此事。$B$B我还是不明白这一切怎么会发生。那些女巫究竟施了什么法术，竟能亵渎那些坟墓的神圣，把安眠其中的死者变成亡灵？', 0),
(175043, 0, 0, 0, 0, 0, 0, 0, 0, '<那东西把痛苦而恳求的目光投向你。>$B$B你……必须……帮帮我们……$B$B我丈夫……他做了些事……$B$B圣光……被污染了……$B$B我们……无法……死去……', 0),
(175046, 0, 0, 0, 0, 0, 0, 0, 0, '你收的货真不错！比我预想的还多！$B$B说好的就是说好的，拿着吧。还有……如果你想给一个卑微的小商人干活，随时再来。', 0),
(175047, 0, 0, 0, 0, 0, 0, 0, 0, '死狗不会咬人……我们这儿是这么说的。不过我不确定这句老话对这帮杂种管不管用。迟早会有更多艾尔迪尔冒出来占住那个洞窟。$B$B他们一向如此。$B$B不管怎么说，斯卡德尔德行省都欠你一份感谢。多亏了你，这段路会太平上一阵子。', 0),
(175048, 0, 0, 0, 0, 0, 0, 0, 0, '那些怪物……裂隙……$B$B你是怎么……？$B$B<霍尔加低声问出最后这句话，随即失去了意识。>', 0),
(175051, 0, 0, 0, 0, 0, 0, 0, 0, '哟，哟！中士一定是心情好得不行；距他上次给我们派援兵已经过去好几天了。$B$B让我好好看看你。<中尉带着戏谑而嘲弄的目光打量你。最后，他在你肩上友好地拍了一下。>$B$B看来你一路过来砍掉了几个脑袋。干得不错，确实不错。干得不错。$B$B保持这股劲头！', 0),
(175053, 0, 0, 0, 0, 0, 0, 0, 0, '人质们安全了。$B$B那些状况较好的决定冒险穿过森林，前往格雷斯基。其余的人已经在旧哨塔里躲了起来。$B$B干得好，$C。', 0),
(175054, 0, 0, 0, 0, 0, 0, 0, 0, '<弗里伦狐疑地打量着那个口袋。看清里面的东西后，他脸上的表情从厌恶变成了激动。>$B$B兽人？在这里？$B$B<有那么一瞬间，那口袋仿佛随时会从他指间滑落。>$B$B那么部落已与霜鬃巨魔结成同盟。那场伏击，这场战争……全都不是偶然。$B我们必须通知格雷斯基。但在此之前，我要你再去办最后一件事。', 0),
(175056, 0, 0, 0, 0, 0, 0, 0, 0, '你的精神为这座哨塔带来了温暖。$B$B你愿意在火边待多久，就待多久。', 0),
(175057, 0, 0, 0, 0, 0, 0, 0, 0, '那个巨魔。那头野兽……他们都死了吗？$B$B<士兵闭上眼睛，许久以来第一次，他感到某种近似安宁的东西。>$B$B没有人能让倒下的战友回到我身边。连圣光也做不到。但你给了我一些几乎接近的东西。$B$B我没有多少东西可以报答你，但我希望能有所表示。请你收下。', 0),
(175059, 0, 0, 0, 0, 0, 0, 0, 0, '<领主指挥官的面孔像一副面具，不泄露任何情绪。但他的眼睛……噢，他的眼睛在预言战争。那份笃定令人胆寒。>$B$B部落。$B$B那么一切都简单了。同时也更加复杂了。$B$B<漫长的沉默。然后他补了一句：>$B$B你超出了我的期望。这种事并不常有。我会确保你得到相应的奖赏。眼下，只要我还担任领主指挥官，就把这座城堡当作你的家。', 0),
(175060, 0, 0, 0, 0, 0, 0, 0, 0, '<中尉深吸一口气；当他嗅到空气中那股灼烧血肉的刺鼻气味时，他眯起了眼睛。>$B$B我知道这不容易……正确的事向来如此。', 0),
(175062, 0, 0, 0, 0, 0, 0, 0, 0, '这是什么？$B$B<他查看羊皮纸时，阿尔卡里安的眉毛从平直的一条变成了尖锐的斜线。当他终于抬起头，眼里满是纯粹的惊慌。>$B$B你说你已经挫败了它？你杀了那些德鲁伊？$B$B<一声如释重负的叹息。他把一只手按在胸口。>$B$B很好。呼。是的。你来找我做得对。是的。是的！我会组织一次调查！就这么办！我保证把这件事查个水落石出。', 0),
(175063, 0, 0, 0, 0, 0, 0, 0, 0, '又一个营地被清除了。$B$B<德雷温的呼吸沉重。他的气息尖锐而破碎。>$B$B至少这一次，我们的人没有一个牺牲。$B$B感谢你的效力。', 0),
(175067, 0, 0, 0, 0, 0, 0, 0, 0, '多萝西……？哦……$B$B<看到那包食物，你看见她眼中的希望熄灭了。>$B$B是费尔纳德让你来的。我……我想，谢谢你。可我没有胃口。女儿下落不明，我没办法干坐着什么也不做。$B$B我必须找到她！', NULL),
(175068, 0, 0, 0, 0, 0, 0, 0, 0, '你杀了他们……是不是？$B$B也许你该再多杀一些。直到一个鱼人也不剩。$B$B多萝西不该遭这种事。我也不该失去她……$B$B他们把她从我身边夺走了。让他们把多萝西还回来。$B$B<拉尔达放声痛哭。>', NULL),
(175069, 0, 0, 0, 0, 0, 0, 0, 0, '你说什么也没找到，这是什么意思？可那些鱼人……多萝西……$B$B<拉尔达的目光暗了下来。>$B$B你是不是有事瞒着我？你不敢的！就算多萝西没有……就算她……<她使劲咽了一下。喉咙里的硬块还在。>我宁愿知道真相，也不想活在忐忑不安里。$B$B那就告诉我。你一定找到了什么。$B$B她还活着吗？求你！$B$B<拉尔达崩溃大哭。>', NULL),
(175070, 0, 0, 0, 0, 0, 0, 0, 0, '他们死了吗？他们受罪了吗？他们痛苦地尖叫了吗？$B$B<仇恨在拉尔达眼中烧得如此猛烈，几乎让人觉得她的泪水正在蒸发。>$B$B我敢肯定，这还远远不够。', NULL),
(175071, 0, 0, 0, 0, 0, 0, 0, 0, '你说什么也没找到，这是什么意思？你确定？多萝西一点踪迹都没有？不可能……不可能……不可能！$B$B她父亲罚了她，把她带去和狗头人待的矿洞了。她一定在那儿！$B$B你找得不够仔细……你得回去，再仔细找找。她一定在那儿……就在某个地方。', NULL),
(175072, 0, 0, 0, 0, 0, 0, 0, 0, '收下这个吧，虽然微薄，就当是你辛苦一趟的补偿。$B$B谢谢你关心我的女儿——愿圣光护佑她——也谢谢你照顾我可怜的妻子。', NULL),
(175073, 0, 0, 0, 0, 0, 0, 0, 0, '你说格雷斯基来的？多尔克雷斯特那个老吝啬鬼……要是随他的意，他能把我每一块奶酪都囤起来。$B$B告诉他别担心：他的订单我一转眼就能备好。$B$B说实话，我的名声大半要归功于格雷斯基人。南方诸省在几位贵族的压力下，除了阻挠出口什么也不干。$B$B你知道吗？那是他们的损失。我们的奶酪是整个暴风城王国里最好的。', NULL),
(175074, 0, 0, 0, 0, 0, 0, 0, 0, '看这颜色！闻起来多香啊！丝一般顺滑，浓郁甘甜，还有一股清新的香气，让人想起风袭的翠绿草甸……$B$B没有什么，绝对没有什么，比得上我们奶牛产的奶。', NULL),
(175076, 0, 0, 0, 0, 0, 0, 0, 0, '你把它们剪得真俊！也瘦了不少，没错，$gsir:ma\'am;。干得漂亮。要是我掉几斤肉也能这么容易就好了……$B$B多谢你帮忙。想看看风袭的羊毛到底有多好？这顶帽子送你。我正好用你带来的这些羊毛给自己再做一顶。', NULL),
(175077, 0, 0, 0, 0, 0, 0, 0, 0, '干得好！我代表影井和风袭谢谢你。这头狼给大家添的麻烦，比任何一头都多。', NULL),
(175078, 0, 0, 0, 0, 0, 0, 0, 0, '你是什么人，佣兵？随你；就算你是披着唤星者外衣的鱼人我也不在乎。事实是，我需要有胆气的人，那种不会轻易退缩的人。$B$B这不是格雷斯基这几周打的那种小打小闹。这是战争。真正的战争。要是安德拉斯特要塞陷落，黑石兽人就会像瘟疫一样蔓延整个行省。', NULL),
(175079, 0, 0, 0, 0, 0, 0, 0, 0, '你是阿拉塞尔那伙的？嗯。很好。你在下面打得不错。', NULL),
(175080, 0, 0, 0, 0, 0, 0, 0, 0, '那些黑石投石车越来越成问题，我的士兵推进得不够快，根本冲不到跟前。你帮了大忙，$C。', NULL),
(175081, 0, 0, 0, 0, 0, 0, 0, 0, '摩尔派你来的？看来指挥官还没把我忘了。$B$B依我的经验，我告诉你：战斗会让人胃里发紧、肠子发松。但胜利……胜利之后总是跟着饿得发疯的胃口。而我一个人可喂不饱整座要塞。$B$B你要想帮上忙，就做好准备弄脏双手吧。', NULL),
(175083, 0, 0, 0, 0, 0, 0, 0, 0, '一张友善的面孔。近来我们很少见到这样的人。仿佛这世界已经充满了阴影。$B$B来吧，告诉我们：是什么让你来到这里？$B$B<精灵的目光仿佛剥开了你的来意。他点了点头，似乎明白了。>$B$B啊，是猎人派你来的。我知道安德拉斯特的人是怎么说我们的！莫向精灵求忠告，因为他们会既说行又说不行。$B$B<他笑了。>$B$B可忠告是危险的礼物，即便智者予智者，而所有的路都可能走岔。$B$B不过，我们还是会尽力帮你。', NULL),
(175084, 0, 0, 0, 0, 0, 0, 0, 0, '要不是亲眼看见，我绝不会相信。那瓮魔法之水为这些人所做的一切，就算是十个圣骑士也做不到。$B$B我早知道山谷里的精灵是强大的盟友，但考虑到他们内向的性情，我一直宁愿让他们置身这场战争之外。$B$B也许我该重新考虑了。', NULL),
(175085, 0, 0, 0, 0, 0, 0, 0, 0, '他们当中不止一个人哭了。可怜的家伙。$B$B我们的世界很残酷。但若不先扯掉他们眼前的遮布就把他们送上战场，那才是残酷得多。', NULL),
(175088, 0, 0, 0, 0, 0, 0, 0, 0, '<萨玛拉急切地接过文件。直到读完，她才重新抬眼看向你。她的神色阴沉。>$B$B库尔甘死了，这消息我喜欢。但事情还没完。差得远呢。', NULL),
(175089, 0, 0, 0, 0, 0, 0, 0, 0, '好。这能拖住他们。至少能拖到我们的警告及时送到北郡。$B$B这么多杀戮……<萨玛拉疲惫地揉着太阳穴。>可它自有意义：$B$B我们战斗、流血、流汗，好让别人不必见识战争的恐怖。好让暴风城的人民能够安宁地生活。', NULL),
(175090, 0, 0, 0, 0, 0, 0, 0, 0, '<尽管指挥官摩尔每隔几秒就要吼出几句命令，他还是专心听完了你的汇报。>$B$B所以他们是要去北郡。$B$B我明白了。$B$B你为我们赢得了时间，$N。足够避免一场悲剧。$B$B这座要塞感谢你。', NULL),
(175091, 0, 0, 0, 0, 0, 0, 0, 0, '你……你不是兽人吧？$B$B<达文长长地吐出一口气，仿佛已经憋了几个小时。>$B$B以我祖先的胡子起誓！我从没这么害怕过！石头开始乱飞、那些战号响起来的时候……我以为他们肯定会找到我。', NULL),
(175092, 0, 0, 0, 0, 0, 0, 0, 0, '我们来看看这是什么？$B$B<达文的目光扫过黑铁矮人的信件，眉头越皱越紧，忧虑渐深。>$B$B公会。他们自称影燃公会。那么，他们就不是寻常的黑铁矮人了。$B$B而这个……<矮人的目光沉了下来。>$B$B这可不妙。', NULL),
(175093, 0, 0, 0, 0, 0, 0, 0, 0, '<巴林听你讲述，不知是出于耐心还是漠不关心。实在看不出来。>$B$B安德拉斯特，是吗？那是在……南边，对？$B$B在我看来，那不是我们的问题。一个黑铁教派，妄想把他们氏族从炎魔的枷锁下解救出来？这满是一股内战的味道。$B$B我说，就让他们自相残杀好了。', 0),
(175094, 0, 0, 0, 0, 0, 0, 0, 0, '谢谢你。我想，还不像看上去那么糟。只是一道擦伤，可疼得像是被人捅了一刀。$b$b愿圣光保佑埃伦德尔，是他派你来找我的。也保佑你，感谢你伸出援手。$b$b这些小精灵……哎哟！', 0),
(175095, 0, 0, 0, 0, 0, 0, 0, 0, '这些已经绰绰有余了。谢谢你，朋友。$b$b别为我担心。我会用你带来的贝洛莱特调一剂药膏，只是要花些时间。无论如何，我已经没有性命之忧了。$b$b请上路吧。别为了我白白留在这里。你帮我的，我已经感激不尽了。', 0),
(175096, 0, 0, 0, 0, 0, 0, 0, 0, '原来你是圣所来的。阿玛兰瑟女士的直觉没错：森林正变得愈发躁动。$b$b原因就是那些血精灵。他们毫无节制地汲取山谷的魔力，扰乱了平衡。他们带来了那些邪恶的水晶，正用它们抽干林间的生气。$b$b于是森林开始反抗。$b$b危险比你猜想的还要大。因为这片森林并不只是一片森林。', 0),
(175098, 0, 0, 0, 0, 0, 0, 0, 0, '一切生命都珍贵，你救下的每一位树妖都算数。$b$b我由衷地感激你，$r。', 0),
(175099, 0, 0, 0, 0, 0, 0, 0, 0, '考拉诺斯的警告恐怕来得太迟了。就在片刻之前，血精灵击碎了封住厄尔达娅之厅的防护法印。$B$B我已派出最精锐的战士，圣所的精英。但他们还不够。$B$B我们需要你。', NULL),
(175100, 0, 0, 0, 0, 0, 0, 0, 0, '那是个陷阱。他们杀光了所有人……怎么会有那么多人混进外交随行队？我早该想到的。我早该……！$B$B<一阵剧烈的咳嗽打断了这位黑暗游侠。她胸前的伤口渗出一股黑色的液体，看上去极是污秽。>$B$B他们是一个教派。我相信他们自称家族。我试图阻止他们，却差点落得和你们圣所那位女士派来的战士一样的下场。和所有其他人一样的下场……', NULL),
(175101, 0, 0, 0, 0, 0, 0, 0, 0, '我听见他们的惨叫了。我听见他们的惨叫了……', NULL),
(175102, 0, 0, 0, 0, 0, 0, 0, 0, '原来真是一个教派。真遗憾。这会让我国与血精灵的关系更加复杂。而且毫无疑问，它还会引起部落与联盟双方的猜疑。$B$B奈纳拉从未见过这般暴行。我们也从未需要如此哀悼自己的同胞。$B$B但危险已经过去，山谷重又呼吸。假以时日，森林会愈合；我们也会愈合。纳玛丽恩圣所将再次听到欢笑与歌声。', NULL),
(175103, 0, 0, 0, 0, 0, 0, 0, 0, '你。你来了！$B$B这是啥？$B$B<阿尔托·比尔伯格闻了闻那粒种子。那气味起初像是让他退缩，随后他的瞳孔却放大了。>$B$B我们种？这个治病？不是巫术。不一样的法术。更强。$B$B花……我喜欢花。', NULL),
(175106, 0, 0, 0, 0, 0, 0, 0, 0, '他们都……？你懂的。<丹多用拇指在自己脖子上一划，随后发出一个古怪的声音，把舌头歪向一边。>$B$B好，好。是啊。啊……$B$B<一阵突如其来的忧伤笼罩了他，他的肩膀垮了下来。>$B$B不，不。我没事。只是……既然你已经解决了艾尔迪尔人，我就没有理由留在这里了。可我不想离开纳玛丽恩圣所。我不想回格雷斯基去。', NULL),
(175107, 0, 0, 0, 0, 0, 0, 0, 0, '你是德雷温爵士信得过的人，对吧？$b$b那就欢迎来到碎岩吧。在这村子遭难之前，我来过不止一次。我总觉得他们都是些恋家的本分人。', 0),
(175109, 0, 0, 0, 0, 0, 0, 0, 0, '<这女人形销骨立：头发乱成一团，衣裳破破烂烂，双脚又黑又血污。她看上去简直像个艾尔迪尔。>$b$b你把那些怪物都了结了？那我们该比怕它们更怕你才是。你……你是我们这边的，对吧？', 0),
(175110, 0, 0, 0, 0, 0, 0, 0, 0, '果然是我想的那样。你说矿洞里躲了多少人？$b$b<坦德尔眯起眼睛，眉头紧锁，缓缓摇了摇头。>$b$b这么少。实在太少了。就算我们把被掳走的人一个不落地救回来，这座村庄也再也缓不过来了。', 0),
(175111, 0, 0, 0, 0, 0, 0, 0, 0, '啊，一张友善的面孔！圣光在上，要是再跟泰尔佩里昂待上一天，我就得掐死他，哪怕只为让他那张脸松一松；他皱了一整天的眉。$B$B说说，你叫什么名字？是那个矮个子派你来的吧？你在碎岩查到什么了吗？$B$B恐怕我们没什么进展。我们既不知道俘虏被带去了哪里，也不知道为什么。', 0),
(175114, 0, 0, 0, 0, 0, 0, 0, 0, '你杀了他？圣光在上，你真的杀了他！$B$B<劳瑞林热情地拥抱了你。>$B$B他一死，布赖卡格高地的艾尔迪尔就再也威胁不到我们的人手了。你知道有句话怎么说来着：死狗……$B$B咬不了人。', 0),
(175115, 0, 0, 0, 0, 0, 0, 0, 0, '艾尔迪尔的符文起着锚点的作用。他们借符文引导从这片土地自然流淌的魔力。那是黑暗的魔法，被污染的魔力。$B$B这个问题困扰了我很久，但我相信，研究你带来的这些符文石，我会对这暗影的本质得到不止一点洞见。$B$B我感谢你。', 0),
(175116, 0, 0, 0, 0, 0, 0, 0, 0, '女巫死了。是的，我感觉到了；像重担变轻，像疼痛变得好受些。$B$B那么，不会再有噩梦了。不会再有夜惊。不会再有疑神疑鬼。$B$B终于，我可以专心做我真正来这里要做的事了。', 0),
(175117, 0, 0, 0, 0, 0, 0, 0, 0, '<黛尔德拉指尖长着不可思议的长甲，她抓挠你的肋腹，抚摸你的额头。>$B$B好猫，没错。多俊的一只小猫。$B$B是什么把你引到我这小屋来的，嗯？让我猜猜！你想让我吐出我们的计划？我们最黑暗、最甜美的秘密。你就喜欢这样，对吧，小花瓣？$B$B<黛尔德拉发出残忍的尖笑。>$B$B愚蠢的$gboy:girl;。你以为这么粗浅的法术能骗过我？来吧，别演了。我们面对面地谈，你和我。', 0),
(175118, 0, 0, 0, 0, 0, 0, 0, 0, '盘根之影。光是念出它的名号，连阳光都会枯萎。$B$B我会帮你把那些可怜人从祭坛上救下来。但是，若要阻止摩根娜，我们也必须准备好牺牲，准备好拿一切去冒险。', 0),
(175119, 0, 0, 0, 0, 0, 0, 0, 0, '我们如何破解压在那些艾尔迪尔身上的诅咒，消息已经传开了。他们看见你从我的小屋出去，所以认定这是我们干的：我的魔法加上你的蛮力。$B$B要是他们知道只要击碎面具就够……可我更喜欢现在这样；就让他们怕我们吧。', 0),
(175120, 0, 0, 0, 0, 0, 0, 0, 0, '你拿到巨鹿的祝福了吗？$B$B拿到了。我在这儿都能感觉到它从你身上散发出来。$B$B很好。', 0),
(175121, 0, 0, 0, 0, 0, 0, 0, 0, '我正忙着呢，你难道没看见！搞什么鬼——$B$B<你把那瓶毒药一亮出来，厨师立刻住了口，声音随即压低成耳语。>$B$B这么说，是他们派你来的。行吧。为什么不呢？不是说事不过三吗？我正要把面包烤完。塞伦娅女士就爱配上一杯酒把它送下肚。', 0),
(175123, 0, 0, 0, 0, 0, 0, 0, 0, '我的心早已停止跳动。这些年来，我从未停止向圣光祈求一个答案：$B$B‘为什么是我？’$B$B我的丈夫曾是斯卡德尔德的领主，而我能想到的、唯一能纪念他的方式，唯一能让我这具怪诞的存在获得意义的方式，就是治理这片领地。守护它。$B$B但如今我看清了，圣光为我安排的究竟是什么。$B$B这是唯一剩下的路。', 0),
(175124, 0, 0, 0, 0, 0, 0, 0, 0, '这是……$B$B<黛尔德拉以一种近乎贪婪的神情端详着塞伦娅女士的戒指。这枚戒指的工艺精妙绝伦，你从未见过这样的东西；单是镶嵌其中的那颗蓝宝石，价值就超过艾尔迪尔所有珠宝的总和。>$B$B那么，你把她杀了。消息传开也用不了多久。$B$B好。很好！如今塞伦娅已经出局，只剩下摩根娜了。', 0),
(175125, 0, 0, 0, 0, 0, 0, 0, 0, '摩根娜的魔典！几个世纪的知识，在最为黑暗的仪式与咒术中酝酿发酵。$B$B她所举行的那个仪式的细节，必定就记载在这些书页之中。$B$B我需要时间来细细研读。', 0),
(175128, 0, 0, 0, 0, 0, 0, 0, 0, '还有幸存者？我这就派一队最精干的部下赶去海滩，立刻把他们护送到安全的地方！', 0),
(175129, 0, 0, 0, 0, 0, 0, 0, 0, '瞧你回来这一身血。$B$B<气味飘过来，矮人皱起了鼻子。>$B$B鱼人？不过……这味道不太一样。啊，算了。看来你把它们狠狠收拾了一顿。很好。让它们哭嚎着爬回海里去吧。离我们的海岸越远越好。我们现有的麻烦已经够多了。', 0),
(175139, 0, 0, 0, 0, 0, 0, 0, 0, '警报全停了！哈！$B$B让我算算……$B$B<他低声嘟囔着，每说一个字就在机械控制台上敲一下。>$B$B胶带的耐久度为 7 比 3……数量减少了 15 这个数值……温度在 6 到 7 度之间波动……而地铁的流量增加了‘2E’……$B$B<他猛敲一个按键，结果立刻出来了。他兴奋地喊道：>$B$B百分之一百三十七！', NULL),
(175140, 0, 0, 0, 0, 0, 0, 0, 0, '<报警机器人像鸭子一样摇摇晃晃地走了过来。它每次闪起红光都刺得你睁不开眼，可你仍能从它的螺栓间感到一种鲜明的机械式惶恐。>$B$B警告！需要行动！$B警告！警告！', NULL),
(175144, 0, 0, 0, 0, 0, 0, 0, 0, '<诺丁摇摇头，把一束线缆接到报警机器人身上，几秒钟就把它拆成了零件。他撬出部件、把电路插进中央主机时，报警机器人发出痛苦的尖叫，灯光胡乱闪烁。>$B$B一场由黑铁巫师策划的袭击？还带着一支听他调遣的穴居怪大军！$B$B我真不知道该怎么看待这件事。这种规模的进攻需要准备。需要组织。需要图谋。$B$B黑铁矮人到底想从这一切中得到什么？', NULL),
(175147, 0, 0, 0, 0, 0, 0, 0, 0, '肮脏的家伙……杀它们都让我恶心。它们的血玷污了雪地。它们的脚印弄脏了我们的路。那可恶的两趾脚掌！$B$B至少死了以后，它们不会再呼吸我们的空气。我们山间的风。$B$B要是我还剩一点力气，真想好好抱你一下！', 0),
(175148, 0, 0, 0, 0, 0, 0, 0, 0, '数量不多，不过，我本来抱的就是痴心妄想。$B$B运气好的话，等我们夺回寒冬之路，道莫尔峰的布罗姆利能匀出几只他自己的狮鹫。', 0),
(175149, 0, 0, 0, 0, 0, 0, 0, 0, '这个……$B$B<达格兰缓缓放下步枪。>$B$B我敢说，那颗头上写满了埃尔德鲁因的手艺。看来那老倔驴还活着，是吧？话说回来，我要一颗巨魔脑袋做什么？$B$B真是够阴森的，这一整套。$B$B不过既然你来了，我倒正缺一双帮手。', 0),
(175150, 0, 0, 0, 0, 0, 0, 0, 0, '很好。$B$B没了部落撑腰，这就等于把他们打回石器时代。', 0),
(175151, 0, 0, 0, 0, 0, 0, 0, 0, '我从上面全看见了，没错。$B$B做对的事，从来都不容易。', 0),
(175152, 0, 0, 0, 0, 0, 0, 0, 0, '啊，我的朋友！$B$B我猜，要是你没来，这个故事会有完全不同的结局。$B$B我叫斯里姆斯，人称迷途者。我是这里的守望者。$B$B我承认，这里的日子曾经好过得多……$B$B不过客套话就到此为止。这里发生的事，一万年来前所未有。', 0),
(175153, 0, 0, 0, 0, 0, 0, 0, 0, '你很有胆量，屠杀了这么多我的信徒之后还敢站在我面前。$B$B不过我仍觉得你很有趣。而且你也许还有用处。$B$B你来这里，是因为你在寻求答案，不是吗？$B$B我会把答案给你。', 0),
(175154, 0, 0, 0, 0, 0, 0, 0, 0, '这是我的神殿。或者说，它曾经是。$B$B那些畸变之物杀光了我的祭司，赶走了信徒。', 0),
(175155, 0, 0, 0, 0, 0, 0, 0, 0, '更糟的是：病光之子从未离开过他们那片受辐射的土地这么远。$B$B我相信他们是看准了部落这场战事带来的机会，抓住时机从背后袭击了霜鬃大军。', 0),
(175156, 0, 0, 0, 0, 0, 0, 0, 0, '<你每说一句，鲍格沃夫的眉头就皱得更深。>$B$B诺莫瑞根的辐射催生出的教派？一个发了疯的巨魔神灵？$B$B我会派人北上核实这些说法。毕竟，正如你自己承认的，你的消息来自一个巨魔幽灵。而谁都知道那些恶鬼是什么德性：$B$B满口谎言，扭曲乖张，一肚子坏水。', 0),
(175158, 0, 0, 0, 0, 0, 0, 0, 0, '我们两族之间那本血账，又添了一笔。$B$B待清的旧怨，少了一桩。$B$B那些野蛮人死了反倒干净。他们活着、呼吸着我们的空气、用他们可憎的脚踩脏我们的雪，本身就是对造物者遗产之美的侮辱。', 0),
(175159, 0, 0, 0, 0, 0, 0, 0, 0, '她死了；我知道。圣光已低声告知了我。$B$B教会感念你，而尽管我无法替他们说话，我猜那些被你从女巫的饥渴中救下的巨魔亡魂，也同样感念你。', 0),
(175161, 0, 0, 0, 0, 0, 0, 0, 0, '<矮人对着你带来的那些肉重重拍了一巴掌。>$B$B这才叫好东西！干得漂亮。虽说没堆成一座山，但也足够我们撑过今天了。$B$B拿上你那一份吧，小子！', 0),
(175174, 0, 0, 0, 0, 0, 0, 0, 0, '手执蜡烛，皮肤发紫，牙齿打颤……你是为团结火盆而来的，对吧？$B$B<恩里尔缓缓摇头，仿佛在自言自语。>$B$B恐怕我帮不了你。', 0),
(175176, 0, 0, 0, 0, 0, 0, 0, 0, '你把它们解决了。$B$B我能看出来，因为这里没那么刺骨了，你不觉得吗？$B$B这座山峰的泥土从未从积雪下露出过，也永远不会；我早已习惯了。可那些该死的元素……它们居然让我打了个寒颤！', 0),
(175177, 0, 0, 0, 0, 0, 0, 0, 0, '一份木柴的供奉。$B$B我的饥渴已经等得不耐烦了。不过，我并不认得你的面孔。$B$B告诉我……那些寒霜恶魔没有伤到我的守焰者吧？', 0),
(175181, 0, 0, 0, 0, 0, 0, 0, 0, '纵然信仰有别，我们在圣光之中皆为一体：农夫、矿工，或是像霍尔多尔那样的勇士。国王与领主亦然。$B$B愿圣光指引你的脚步，我的孩子。', 0),
(175198, 0, 0, 0, 0, 0, 0, 0, 0, '我叔叔……？根本不必派人来。我不过是照本分履行职责。$B$B门口的情况还在掌控之中……只是“掌控”这个词，如今听起来已经算是客气了。$B$B不管怎样，谢谢你费心来搭把手。$B$B希望我叔叔和贵族议会能早点肯动手。', 0),
(175201, 0, 0, 0, 0, 0, 0, 0, 0, '管他有没有诅咒，格雷斯基那边总想听你的报告。总比什么都不做强，我想。$B$B我就留在这儿；你懂的，万一情况有变。', 0),
(175202, 0, 0, 0, 0, 0, 0, 0, 0, '<德雷温爵士以极大的耐心听完了你的讲述。>$B$B矿洞塌方。矿工被困。绝望之中，矿工们以人肉为食。而后不久，他们便遭了诅咒，被变成豺狼人，作为惩罚。$B$B<有那么一瞬，你担心德雷温爵士会放声大笑。>$B$B也罢，在斯卡德尔德，人们见过比这更怪的事。我会让人进一步调查此事。$B$B在那之前，格雷斯基感谢你。', 0),
(175203, 0, 0, 0, 0, 0, 0, 0, 0, '阿兰娜，可怜的孩子。$B$B<三个女人——少女、妇人、老妪——同时开口，声音整齐划一。>$B$B我们早知道会走到这一步，却未曾干预。我们从不干预。可斯卡德尔德并非像我们这般；绝非如此。而那可怜、可怜的人，被诱惑得实在太容易了。$B$B你是为他强加于挚爱之人身上的那诅咒般的存在而来的，对吗？', 0),
(175204, 0, 0, 0, 0, 0, 0, 0, 0, '诅咒正在消退。没有哪场雨会永远下下去。$B$B<三姐妹异口同声，声音严丝合缝。她们眼中闪过认出的光。>$B$B卡登的罪已得赎偿，大轮回的平衡已然恢复。$B$B阿兰娜很幸运，找到她的人是你，而不是别人。', 0),
(175205, 0, 0, 0, 0, 0, 0, 0, 0, '我收到了埃尔罗斯神父的信。他说不清是怎么回事，但墓室里的威胁似乎已经解决了。$B$B看来是该派人去那儿扫一扫了。$B$B<德雷温爵士从铺满桌面的文书上抬起目光，赞许地朝你点了点头。>$B$B我不知道你做了什么，但它起效了。$B$B格雷斯基感谢你。', 0),
(175207, 0, 0, 0, 0, 0, 0, 0, 0, '<这人的衣着表明他是个外乡人。深暗而低调的色调，连同他那匹坐骑的姿态，都指认他是斯卡德尔德省的居民。>$B$B<他浓密的眉毛让他的目光带上几分严厉。>$B$B有事吗？', 0),
(175208, 0, 0, 0, 0, 0, 0, 0, 0, '<卡拉诺斯的登山队长以一份拿捏得恰到好处的耐心听你说话。>$B$B那么是格拉姆吉尔派你来的。从格雷斯基到这儿，路可不短。', 0),
(175323, 0, 0, 0, 0, 0, 0, 0, 0, '就是它！$B$B<艾什琳轻手轻脚地接过心脏，却没有半点嫌恶之色。看她手上的熟练，你几乎会以为她早就习惯摆弄这玩意儿和别的脏器。>$B$B有了这个，再加一点炼金术，我就能给自己熬一剂药，对这可怜的干嗓子妙用无穷。', 0),
(175324, 0, 0, 0, 0, 0, 0, 0, 0, '牙齿带来了吗？$B$B<艾什琳双手捧成杯状，一颗接一颗地接过牙齿；有些还带着血。>$B$B那么这些是……$B$B熊牙，没错。$B$B<她似乎松了口气。>$B$B很好。拿着这个，算是辛苦费。', 0),
(175325, 0, 0, 0, 0, 0, 0, 0, 0, '你……感觉到了吗？$B$B即便已经死去，这只乌鸦的眼睛里仍残存着一缕魔法。$B$B<黑色的瞳孔映出艾什琳扭曲的脸，还有你的。>$B$B就像一面虚假的镜子。仿佛有人站在另一侧……注视着。$B$B我能给你一句忠告吗？$B$B若我是你，我会避开乌鸦的视线。', 0),
(175326, 0, 0, 0, 0, 0, 0, 0, 0, '你倒真是有胆量。而且这胆量还用对了地方。$B$B给你，如约付酬。', 0),
(175327, 0, 0, 0, 0, 0, 0, 0, 0, '你找到她了！$B$B<乌莉拉端详着那块消化了一半的肉屑，上面沾满胆汁与胃酸。>$B$B是她。毫无疑问，就是她。$B$B你不知道我有多感激。$B$B哦，佩图尼亚，我可怜的佩图尼亚。我不是跟你说过，夜里不要离开鸡舍吗？', 0),
(175328, 0, 0, 0, 0, 0, 0, 0, 0, '<听着你讲述克雷斯特海恩发生的事，牧师灰色的眉毛给他的目光添了几分怀疑。>$B$B发光的……亡者？$B$B这种事根本不可能。定是艾尔迪尔人的魔法搅乱了你的感官。埃尔罗斯尽管受过训练，骨子里仍是个十足的……乡巴佬。$B$B迷信。$B$B没有什么可查的。不过是某个艾尔迪尔女巫在那地穴里施展了死灵法术。仅此而已。', 0),
(175332, 0, 0, 0, 0, 0, 0, 0, 0, '好，这正是我要找的东西。$B$B<埃德伦从那一堆里取出一件饰品，举到眼前。>$B$B我不是行家，但我读过堆积如山的书，讲的是霜鬃巨魔，以及他们的王国如何毁于矮人之手。$B$B我会设法弄清这些饰品里藏着什么样的魔法，以及我们该如何破解它。', 0),
(175333, 0, 0, 0, 0, 0, 0, 0, 0, '唉。你根本不知道自己给我带来了多宝贵的东西。$B$B如果我没弄错，这刻的是霜鬃人的死亡洛阿。托特兹，或者托兹克，大概是这一类。我也不知道该怎么念。$B$B给你。这是我身上仅有的了。', 0),
(175334, 0, 0, 0, 0, 0, 0, 0, 0, '愿森林的诸神——我是说，愿圣光保佑你！$B$B这绰绰有余了。顺说一句，这肉切得还不赖。$B$B你要是哪天闲下来……我能在拔毛乌鸦的厨房里给你找点活干。', 0),
(175339, 0, 0, 0, 0, 0, 0, 0, 0, '<莫里克在皮子上反复摸索，寻找瑕疵。他一言不发，手也不停，直到他终于确信你带来的确实是一张毫无瑕疵的皮子。>$B$B这就可以了。现在我只能指望我这双笨手，能缝出一件配得上我妻子的大衣。$B$B给你，如约付酬：', 0),
(175342, 0, 0, 0, 0, 0, 0, 0, 0, '<达纳尔在黑色毛皮上摩挲着双手，欢喜得几乎翻起了白眼。随后，他用一种尖细而做作的嗓音补充道：>$B$B瞧瞧这质地，妙极了。做件外套都行！或者斗篷。大概还是块地毯最合适。哪怕做条毛毯呢！$B$B拿着吧，这是给你的辛苦费……', NULL),
(175344, 0, 0, 0, 0, 0, 0, 0, 0, '亡灵……竟被圣光触碰过。$B$B这算是……？这怎么可能……？$B$B<有一瞬间，恐惧让阿比盖尔完全动弹不得。那既是肉体上的恐惧，也是信仰上的恐惧。>$B$B你在这里做了一件高尚的事，$r。去吧。我会留在这里，确保没有任何一个这种恶物能逃过我剑锋的怒火。', 0),
(175345, 0, 0, 0, 0, 0, 0, 0, 0, '那份寂静……在那么多尖叫声中，我几乎忘了寂静是什么声音了。$B$B拿着。这是给你的辛苦费。', 0),
(175346, 0, 0, 0, 0, 0, 0, 0, 0, '<基尔达听着你的汇报，眉头越皱越紧。无论参议员雷德斯通对这件事怎么看，这位队长显然不会那么轻易就把它撇到一边。>$B$B黑铁邪教徒、暗影、火焰……是啊，这可不是酒馆里的闲话，笑一笑就能揭过去。$B$B你把这件事告诉我，做得很好。我会确保艾达·冈巴德收到消息，也让我们边境上的眼线知道该提防什么。$B$B若安德拉斯特以南真有什么麻烦在酝酿，我宁愿在它敲响我们的门之前就先听到它的动静。', 0),
(175347, 0, 0, 0, 0, 0, 0, 0, 0, '嗯……我们这儿有什么？$B$B<贝尔德雷德在她那长长的鼻子的阴影下打量着矿石。>$B$B这些石头上散发的魔法气息……我很熟悉。$B$B把你找到的东西全都给我，从今往后，离这种矿石远一点。$B$B前提是你还想保住你那点可怜的理智——毕竟你居然来求我帮忙……$B$B<她发出一阵尖利的笑声。>', 0),
(175348, 0, 0, 0, 0, 0, 0, 0, 0, '<德雷温爵士仔细听着你关于丹卡扎德处境和他们所面临麻烦的汇报。>$B$B<然后，他笑了。>$B$B你为我们这些矮人邻居做了不少好事。$B$B只要我们有能力，我就会想办法从格雷斯基派出增援。', 0),
(175349, 0, 0, 0, 0, 0, 0, 0, 0, '那是……？$B$B<乌莉拉接过小瓶的郑重模样，就像神父在弥撒前接过一件圣物。>$B$B我快疯了。我几乎坐不住！一整天从屋里踱到屋外，又从屋外踱回来。$B$B虽然我当初已经预付过钱了，还是请收下这个。算是给你的辛苦费。', 0),
(175350, 0, 0, 0, 0, 0, 0, 0, 0, '<奶牛的眼睛像木桩一样钉在你身上。那黑色瞳孔后面有什么在游动，唤醒了你心底那股原始的逃遁冲动。>$B$B<一个声音强行挤进你的思绪。奶牛的眼睛是两口深黑的井。>$B$B“你做得很好。现在走吧。不要向任何人提起我。”', NULL);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(175001, 0, 0, '与这些人周旋，既繁琐又令人疲惫……', 0),
(175002, 0, 0, '欢迎来到达伦加尔家族庄园。', 0),
(175003, 0, 0, '阿拉松的房间在楼上。', 0),
(175004, 0, 0, '<印着联盟徽记的破碎木箱。>', 0),
(175005, 0, 0, '<自你抵达庄园起，队长就一直紧盯着你。>', 0),
(175018, 0, 0, '快告诉我，你把我的一些货找回来了！', 0),
(175020, 0, 0, '只要湖里还有鱼人，我抛多少次竿都没用……你把那些祸害清干净了吗？', 0),
(175021, 0, 0, '啊……请别耽搁太久。你把草采来了吗？', 0),
(175022, 0, 0, '这种任务对你这样的人来说只是小菜一碟……不是吗？', 0),
(175025, 0, 0, '你拿到妖精之尘了吗？', 0),
(175026, 0, 0, '成功了吗？', 0),
(175028, 0, 0, '只要风帆还在转，一切就都好办。$B$B哦……你有事吗？', 0),
(175029, 0, 0, '面包师最主要的材料就是面粉。你拿到了吗，甜食家？', 0),
(175030, 0, 0, '你带来的东西必须新鲜，这一点很要紧。', 0),
(175031, 0, 0, '耐心……这辈子做任何事，最主要的材料永远是耐心。', 0),
(175032, 0, 0, '有收获吗？我的生计可全靠那枚徽章……', 0),
(175038, 0, 0, '求你告诉我，你已经拿到他的头了。', 0),
(175039, 0, 0, '你找到钥匙了吗？', 0),
(175046, 0, 0, '那些鳟鱼连最好的渔夫都能耗住……你抓到它们了吗？', 0),
(175063, 0, 0, '那么，加尔代恩村那边有消息了？说吧。', 0),
(175064, 0, 0, '你带来野猪肉了吗？', 0),
(175065, 0, 0, '你弄完了吗？羽毛带来了吗？', 0),
(175067, 0, 0, '多萝西……？', NULL),
(175076, 0, 0, '出去找羊毛的人，最好当心别自己回来时被剪了个精光。', NULL),
(175088, 0, 0, '你拿的是什么？是给我的吗？', NULL),
(175095, 0, 0, '药草拿到了吗？那毒……已经开始蔓延了。', 0),
(175096, 0, 0, '树之精魂正在哀号。你为它们带来安宁了吗？', 0),
(175117, 0, 0, '<黛尔德拉似乎忙着自己的事，连看你一眼都顾不上。>', 0),
(175118, 0, 0, '听着，听我说。', 0),
(175119, 0, 0, '那些面具你砸碎了没有？还是说一看见它们就怂了？', 0),
(175120, 0, 0, '怎么样？', 0),
(175124, 0, 0, '你办成了吗？', 0),
(175125, 0, 0, '那本该死的书在哪儿？', 0),
(175177, 0, 0, '<一个噼啪作响的轮廓，缠绕着火舌与层层黑烟。>', 0),
(175198, 0, 0, '我劝你这个时候别进斯卡德尔德。', 0),
(175201, 0, 0, '<队长显得忧心忡忡。>', 0),
(175325, 0, 0, '那些乌鸦……如果你之前没注意到，现在想必已经注意到了。$B$B斯卡德尔德到处都是它们。', 0),
(175329, 0, 0, '有什么我能帮你的吗？', 0),
(175330, 0, 0, '约南·塔洛尔，听候差遣。我是本村的村长。$B$B有什么我能帮你的吗？', 0),
(175331, 0, 0, '你有没有给我带什么来？', 0),
(175340, 0, 0, '这么快就回来了？$B<看来你不在的时候，杜拉克一直在喝酒。>', 0),
(175342, 0, 0, '只要你把座狼皮带来了，我就不计较你失礼，也不计较你没有向我鞠躬。', NULL),
(175349, 0, 0, '有什么事需要我帮忙吗？$B$B<一片难看的疹子覆在女人的脸、脖颈和手背上。她抓得太厉害，皮肤都已经破溃了。>', 0);
INSERT INTO `quest_greeting` (`ID`, `type`, `GreetEmoteType`, `GreetEmoteDelay`, `Greeting`, `VerifiedBuild`) VALUES
(164038, 0, 0, 0, '欢迎来到克雷斯特海恩。$B$B<管事久久地打量着你，仿佛在掂量你的分量。>', 0),
(164442, 0, 0, 0, '当霜鬃攻占王者大道的消息传到我们耳中时，丹卡扎德里我们问自己的第一个问题是：“为什么？是什么变了？”$B$B直到不久之前，那些巨魔与其说是威胁，不如说是麻烦。就像一场时令感冒，你懂吧。他们从不敢如此猖狂。$B$B我已经查明了原因。$B$B部落与他们达成了交易。部落为他们提供补给，也在背后操纵一切。', 0);
